  have := d₁ ⨀ h₂;
  exact elim_contra ⨀ this ⨀ h₁;

def explodeHyp (h₁ : 𝓢 ⊢ φ ➝ ψ) (h₂ : 𝓢 ⊢ φ ➝ ∼ψ) : 𝓢 ⊢ φ ➝ χ := by
