  have : 𝓢 ⊢ ∼φ ➝ φ ➝ ∼ψ := explodeHyp₂ explode₂₁ imply₁;
  have : 𝓢 ⊢ ∼(φ ➝ ∼ψ) ➝ ∼∼φ := contraIntro' explode₂₁
