  simp only [LukasiewiczAbbrev.and];
  have : 𝓢 ⊢ (φ ➝ ∼ψ) ➝ φ ➝ ∼ψ := impId _
  have : 𝓢 ⊢ (φ ➝ ∼ψ) ➝ ∼ψ := this ⨀₁ imply₁' hp;
