def explode₂₁ : 𝓢 ⊢ ∼φ ➝ φ ➝ ψ := by
  simp;
  exact dhypBoth efq;

def explode₁₂ : 𝓢 ⊢ φ ➝ ∼φ ➝ ψ := impSwap explode₂₁

